class MedianFinder {
  constructor() {
    this.arr = [];
  }
  addNum(num) {
    let l = 0, r = this.arr.length;
    while (l < r) {
      const mid = (l + r) >> 1;
      if (this.arr[mid] < num) l = mid + 1;
      else r = mid;
    }
    this.arr.splice(l, 0, num);
  }
  findMedian() {
    const n = this.arr.length;
    if (n % 2 === 1) return this.arr[Math.floor(n / 2)];
    return (this.arr[n / 2 - 1] + this.arr[n / 2]) / 2;
  }
}

function solve(operations, values) {
  const res = [];
  let mf = null;
  for (let i = 0; i < operations.length; i++) {
    const op = operations[i];
    const val = values[i];
    if (op === "MedianFinder") {
      mf = new MedianFinder();
      res.push(null);
    } else if (op === "addNum") {
      mf.addNum(val[0]);
      res.push(null);
    } else if (op === "findMedian") {
      res.push(mf.findMedian());
    }
  }
  return res;
}
